  periodoDias = periodoDiasClassificador;
  inicio = new Date(hoje);
  inicio.setDate(inicio.getDate() - periodoDias);
  label = `últimos ${periodoDias} dias`;
} else if (/\bhoje\b/.test(mensagem)) {
  // pediu especificamente "hoje"
  periodoDias = 0;
  inicio = new Date(hoje);
  label = 'hoje';
} else {
  // padrao para relatorio geral sem periodo especifico: mes atual + mes passado
  inicio = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
  const diffMs = hoje - inicio;
  periodoDias = Math.ceil(diffMs / 86400000);
  label = 'mês atual e mês passado';
}

const dataInicio = inicio.toISOString().slice(0, 10);
