const parsed = $('Parsear Resposta IA').item.json;
const periodoDiasClassificador = parsed.entidades.periodo_dias;
const mensagem = (parsed.mensagem_original || '').toLowerCase();

const hoje = new Date(new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' }) + 'T12:00:00Z');
let inicio, label, periodoDias;

if (/\bhoje\b/.test(mensagem)) {
  periodoDias = 0;
  inicio = new Date(hoje);
  label = 'hoje';
} else if (/\bm[eê]s\b/.test(mensagem) && !/\b(passado|anterior)\b/.test(mensagem)) {
  // "esse mês" / "mês atual" -> mês-calendário de verdade, não janela rolante.
  // Prioridade sobre periodo_dias porque o classificador tende a converter
  // "mês" em periodo_dias=30, o que não é a mesma coisa (dia 1 até hoje
  // tem 23 dias em julho, por exemplo, não 30).
  inicio = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
  const diffMs = hoje - inicio;
  periodoDias = Math.ceil(diffMs / 86400000);
  label = 'mês atual';
} else if (periodoDiasClassificador && periodoDiasClassificador > 0) {
  periodoDias = periodoDiasClassificador;
  inicio = new Date(hoje);
  inicio.setDate(inicio.getDate() - periodoDias);
  label = `últimos ${periodoDias} dias`;
} else {
  inicio = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
  const diffMs = hoje - inicio;
  periodoDias = Math.ceil(diffMs / 86400000);
  label = 'mês atual e mês passado';
}

const dataInicio = inicio.toISOString().slice(0, 10);
return [{ json: { dataInicio, periodoDias, label } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const { periodoDias, label, dataInicio } = $('Calcular Período Financeiro').item.json;
const entidades = $('Parsear Resposta IA').item.json.entidades;
const origemAudio = $('Preparar Entrada Agente').item.json.origem_audio;

const hoje = new Date(new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' }) + 'T12:00:00Z');
const hojeStr = hoje.toISOString().slice(0, 10);

let lancamentos = dedupeById($input.all().map(i => i.json));
lancamentos = lancamentos.filter(l => l.data >= dataInicio && l.data <= hojeStr);
if (entidades.tipo_financeiro) {
  lancamentos = lancamentos.filter(l => l.tipo === entidades.tipo_financeiro);
}

let texto;
if (lancamentos.length === 0) {
  texto = `Nenhum lançamento financeiro encontrado (${label}).`;
} else {
  const despesas = lancamentos.filter(l => l.tipo === 'despesa');
  const receitas = lancamentos.filter(l => l.tipo === 'receita');
  const totalDespesas = despesas.reduce((s, l) => s + (Number(l.valor) || 0), 0);
  const totalReceitas = receitas.reduce((s, l) => s + (Number(l.valor) || 0), 0);

  if (origemAudio) {
    let partes = [`Financeiro, ${label}.`];
    if (!entidades.tipo_financeiro || entidades.tipo_financeiro === 'receita') {
      partes.push(`Receitas de R$ ${totalReceitas.toFixed(2)}.`);
    }
    if (!entidades.tipo_financeiro || entidades.tipo_financeiro === 'despesa') {
      partes.push(`Despesas de R$ ${totalDespesas.toFixed(2)}.`);
    }
    if (!entidades.tipo_financeiro) {
      partes.push(`Saldo de R$ ${(totalReceitas - totalDespesas).toFixed(2)}.`);
    }
    texto = partes.join(' ');
  } else {
    const porCategoria = {};
    for (const l of lancamentos) {
      const chave = `${l.tipo} - ${l.categoria || 'outros'}`;
      porCategoria[chave] = (porCategoria[chave] || 0) + (Number(l.valor) || 0);
    }

    texto = `Financeiro (${label}):\n\n`;
    if (!entidades.tipo_financeiro || entidades.tipo_financeiro === 'receita') {
      texto += `Receitas: R$ ${totalReceitas.toFixed(2)}\n`;
    }
    if (!entidades.tipo_financeiro || entidades.tipo_financeiro === 'despesa') {
      texto += `Despesas: R$ ${totalDespesas.toFixed(2)}\n`;
    }
    if (!entidades.tipo_financeiro) {
      texto += `Saldo: R$ ${(totalReceitas - totalDespesas).toFixed(2)}\n`;
    }
    texto += `\nPor categoria:\n`;
    texto += Object.entries(porCategoria).map(([k, v]) => `- ${k}: R$ ${v.toFixed(2)}`).join('\n');
  }
}

return [{ json: { resposta_sugerida: texto } }];

